#!/usr/bin/env python3
# patch-158-G11: fix per-asset part-picker dropdown clipping
"""
When typing in the per-asset "+ Add product..." input, the
autocomplete dropdown was being clipped by the asset card's
overflow:hidden. You could barely see one row at the card edge.

Fix: drop overflow:hidden from .ma-asset. The defensive clipping
wasn't doing meaningful work — child backgrounds don't bleed past
the rounded corners. Added position:relative explicitly to keep
the z-index stacking context clean (the dropdown is z-index:20
within its pickerwrap, which is position:relative).

Single-file CSS-only view patch.
"""
